INSERT INTO "public"."sector_trigger_logs" ("id", "session", "trigger_date", "data_date", "ihsg_price", "ihsg_change", "credits_used", "tickers_selected", "news_fetched", "reasoning", "status", "error_message", "created_at") VALUES ('0a2bebac-66e4-4d03-8239-b7aeed47405d', 'open', '2026-09-17', '2026-09-16', '6436.853', '-0.3760938643613637', 0, 4, 9, 'MBMA & DRMA dipilih karena aksi korporasi nyata (buyback & JV ekspansi EV). MGLV dipilih untuk edukasi risiko diskon besar pasca-divestasi pengendali. SMRA dimasukkan sebagai studi kasus kewaspadaan tata kelola perusahaan (GCG) bagi investor.', 'success', null, '2026-09-17 06:49:24.86414+00'), ('24ecd9fd-0ded-4ab5-9a50-3377039fd8e9', 'open', '2026-09-17', '2026-09-16', '6436.853', '-0.3760938643613637', 0, 4, 9, 'MBMA & DRMA dipilih karena aksi korporasi strategis (Buyback & JV Ekspansi). MGLV dimasukkan sebagai edukasi risiko aksi jual diskon besar pemegang saham pengendali, sementara SMRA sebagai studi kasus kewaspadaan GCG dan isu tata kelola perusahaan.', 'success', null, '2026-09-17 07:54:38.087503+00'), ('511a2ed6-1f72-4f18-b362-ff8d483a5555', 'open', '2026-09-18', '2026-09-17', '6462.431', '0.3973680927620923', 0, 4, 10, 'PTRO dipilih karena pertumbuhan laba masif dan akuisisi strategis. BYAN masuk karena aksi korporasi M&A besar oleh Jhonlin. INET mencerminkan ekspansi bisnis lewat akuisisi. KKGI dipilih untuk kategori value/dividen dengan sentimen positif manajemen baru.', 'success', null, '2026-09-18 07:09:03.875239+00'), ('6b73e037-ad0f-4943-8c10-a1842c6df0c6', 'open', '2026-09-18', '2026-09-17', '6462.431', '0.3973680927620923', 0, 4, 7, 'PTRO dan BYAN dipilih karena katalis akuisisi strategis dan perubahan pengendali. INET dipilih untuk ekspansi bisnis melalui M&A, sementara MBMA mewakili aksi korporasi buyback untuk stabilitas harga. Kombinasi ini mencakup sektor energi, infrastruktur, dan material dasar dengan aksi korporasi yang konkret.', 'success', null, '2026-09-18 03:17:19.00517+00'), ('71ca3d88-32c0-406d-9a03-1ae7e9a7074d', 'open', '2026-09-18', '2026-09-17', '6462.431', '0.3973680927620923', 0, 4, 12, 'PTRO dipilih karena pertumbuhan laba 913% dan akuisisi strategis. BYAN masuk karena aksi akuisisi pengendali baru (H Isam). INET mewakili ekspansi anorganik sektor infrastruktur, sementara IRSX dipilih sebagai contoh turnaround kinerja fundamental yang signifikan (laba naik 587%).', 'success', null, '2026-09-18 12:11:12.947228+00'), ('82361f38-7a9a-4de9-b049-ff9f9010f2d4', 'open', '2026-09-18', '2026-09-17', '6462.431', '0.3973680927620923', 0, 4, 10, 'PTRO dipilih karena pertumbuhan laba 913% dan ekspansi M&A. BYAN dipilih karena aksi korporasi strategis akuisisi pengendali. MBMA dipilih untuk aksi buyback sebagai katalis harga. KKGI dipilih sebagai emiten dividen untuk diversifikasi value.', 'success', null, '2026-09-18 07:01:13.460458+00'), ('93a52bb7-fda1-4d45-8b20-21812bcfb569', 'open', '2026-09-21', '2026-09-18', '6441.159', '-0.329164056064969', 0, 2, 5, 'ULTJ dipilih karena aksi korporasi M&A dan Rights Issue jumbo yang signifikan (katalis utama). BBCA disertakan sebagai representasi indeks untuk edukasi manajemen risiko pasar di tengah volatilitas sentimen global, memberikan perspektif bagi investor mengenai pentingnya saham defensif saat IHSG tertekan.', 'success', null, '2026-09-21 01:00:10.185041+00');